"""
Module for checking critical alarms and Stop whole execution when alarms were detected.
More info:
https://nokia.sharepoint.com/sites/uuf4all/SitePages/Stop&Fix-for-Truck-Roll.aspx
"""
import os
import logging
from robot.libraries.BuiltIn import BuiltIn
from taf.internal.sbts.admin.exceptions import AdminApiException
from taf.rfrl.utilities.robot.general import set_robot_suite_variable, get_builtin_value
from taf.rfrl.utilities.tl_config import is_testline_of_cloud_type
from taf.rfrl.utilities import tl_config
from taf.rfrl.utilities.messenger import send_email_with_default_template
from taf.rfrl.bts.devices.du.du_operations import GnbDuOperations, EnbDuOperations
from taf.rfrl.bts.devices.ru.ru_operations import GnbRuOperations, EnbRuOperations
from taf.rfrl.bts.devices.exceptions import IncorrectRUsStatuses, RUsInfoNotAvailable, IncorrectStatuses


def check_truck_roll_alarms(skip_if_not_commissioned=False):
    """
    Check truck roll alarms for all GNBs and ENBs in testline configuration.
    :param skip_if_not_commissioned: Skip checking if BTS is not commissioned
    :return: None
    """
    truck_roll_alarms = [10, 1806, 4341, 4352, 4383]
    if tl_config.tl.gnbs:
        for gnb_id, gnb in enumerate(tl_config.tl.gnbs):
            if is_testline_of_cloud_type(bts_id=gnb_id):
                continue
            bts_commissioned = _check_bts_is_pingable_and_commissioned(
                bts_type='GNB', bts_id=gnb_id, ignore_if_not_commissioned=skip_if_not_commissioned)
            if bts_commissioned:
                _check_alarms_for_bts(critical_alarms=truck_roll_alarms, bts_type='GNB', bts_id=gnb_id)
                _verify_rus_are_in_truck_roll_state(bts_type='GNB', bts_id=gnb_id)
            else:
                logging.info("Ignoring checking alarms due to BTS not commissioned")
    if tl_config.tl.enbs:
        for enb_id, enb in enumerate(tl_config.tl.enbs):
            bts_commissioned = _check_bts_is_pingable_and_commissioned(
                bts_type='ENB', bts_id=enb_id, ignore_if_not_commissioned=skip_if_not_commissioned)
            if bts_commissioned:
                _check_alarms_for_bts(critical_alarms=truck_roll_alarms, bts_type='ENB', bts_id=enb_id)
                _verify_rus_are_in_truck_roll_state(bts_type='ENB', bts_id=enb_id)
            else:
                logging.info("Ignoring checking alarms due to BTS not commissioned")


def stop_execution_if_truck_roll_alarms_detected(receivers=None, sender='taf.krkpz@nokia.com'):
    """
    Check if TRUCK_ROLL_ALARMS detected and send email notification to receivers
    :param receivers: list of receivers
    :param sender: who sent email
    :return: None
    """
    if get_builtin_value('TRUCK_ROLL_ALARMS'):
        cm_execution_id = os.environ.get("CM_EXECUTION_ID")
        try:
            if get_builtin_value('SEND_TRUCK_ROLL_EMAIL'):
                _send_email_notification(receivers=receivers, sender=sender)
            else:
                logging.warning("Truck roll alarms detected: {}".format(get_builtin_value('TRUCK_ROLL_ALARMS')))
        except Exception as e:
            logging.warning("Cannot send email notification - please check logs")
            logging.debug(repr(e))
        if cm_execution_id is not None:
            logging.error("Stop and Fix error detected. Triggering 20 Hours sleep for manual log collection")
            BuiltIn().sleep("20 hours", reason="Stop and Fix error detected. Waiting for manual logs gathering")
        BuiltIn().fatal_error("Stop and Fix procedure triggered! Aborting test execution.")


def is_truck_roll_alarms_detected():
    """
    Check if TRUCK_ROLL_ALARMS detected
    :return: True if alarms detected, False otherwise
    """
    return bool(get_builtin_value('TRUCK_ROLL_ALARMS'))


def _check_if_bts_commissioned(bts_type, bts_id, du_id=0, interface='mplane'):
    """
    Check if BTS is commissioned.
    :param bts_type: 'GNB' or 'ENB'
    :param bts_id: BTS id
    :param du_id: DU id
    :param interface: Interface type ('mplane' or 'lmp')
    :return: Tuple (commissioned status, message)
    """
    bts = GnbDuOperations() if bts_type == 'GNB' else EnbDuOperations()
    connection_alias = bts.rest_alias.format(bts_id, du_id)
    try:
        logging.debug(f"[{connection_alias}] Checking if BTS is commissioned")
        if interface == 'mplane':
            bts.connect(bts_id=bts_id)
        else:
            bts.connect(bts_id=bts_id, interface='lmp', force=True)
        statuses = bts.admin.get_bts_statuses(connection=connection_alias)
        bts_state = statuses['proceduralState'].lower()
        if bts_state == 'notcommissioned':
            msg = f"[{connection_alias}] BTS is not commissioned"
            logging.debug(msg)
            return False, msg
        msg = f"[{connection_alias}] BTS is commissioned"
        logging.debug(msg)
        return True, msg
    except AdminApiException as e:
        msg = f"[{connection_alias}] Cannot check if BTS is commissioned"
        logging.warning(msg)
        logging.debug(repr(e))
        return None, msg


def _check_bts_is_pingable_and_commissioned(bts_type, bts_id, du_id=0, ignore_if_not_commissioned=False):
    """
    Check if BTS is pingable and commissioned via M-plane or LMP interface.
    :param bts_type: 'GNB' or 'ENB'
    :param bts_id: BTS id
    :param du_id: DU id
    :param ignore_if_not_commissioned: Ignore if BTS is not commissioned
    :return: BTS commissioned status
    """
    bts = GnbDuOperations() if bts_type == 'GNB' else EnbDuOperations()
    connection_alias = bts.rest_alias.format(bts_id, du_id)
    bts_commissioned = None
    comm_msg = None
    if bts.mplane_is_pingable_from_ws(bts_id=bts_id, du_id=du_id):
        logging.info("[{}] M-plane address is pingable from Workstation".format(connection_alias))
        bts_commissioned, comm_msg = _check_if_bts_commissioned(bts_type, bts_id, du_id)
    else:
        msg = "[{}] M-plane address is not pingable from Workstation".format(connection_alias)
        if bts.lmp_is_pingable_from_ws(bts_id=bts_id, du_id=du_id):
            logging.info("LMP address is pingable from Workstation")
            bts_commissioned, comm_msg = _check_if_bts_commissioned(bts_type, bts_id, du_id, interface='lmp')
            if bts_commissioned:
                logging.error(msg)
                _append_to_truck_roll_alarms_variable(msg)
        else:
            msg = "[{}] LMP address is not pingable from Workstation".format(connection_alias)
            _append_to_truck_roll_alarms_variable(msg)

    if not bts_commissioned:
        if ignore_if_not_commissioned:
            logging.info("ignore_if_not_commissioned is set to True")
        else:
            _append_to_truck_roll_alarms_variable(comm_msg)

    return bts_commissioned


def _check_alarms_for_bts(critical_alarms, bts_type, bts_id, du_id=0):
    """
    Check for critical alarms on BTS.
    :param critical_alarms: List of critical alarm IDs
    :param bts_type: 'GNB' or 'ENB'
    :param bts_id: BTS id
    :param du_id: DU id
    :return: None
    """
    bts = GnbDuOperations() if bts_type == 'GNB' else EnbDuOperations()
    connection_alias = bts.rest_alias.format(bts_id, du_id)

    try:
        bts.connect(bts_id=bts_id)
        active_alarms = bts.admin.get_active_alarms(connection=connection_alias)
        for active_alarm in active_alarms:
            if int(active_alarm['faultId']) in critical_alarms:
                msg = "[{}] Detected critical alarm [FAULT_NAME: {}, FAULT_ID: {}]".format(connection_alias,
                                                                                           active_alarm['faultName'],
                                                                                           active_alarm['faultId'])
                logging.error(msg)
                _append_to_truck_roll_alarms_variable({'msg': msg, 'alarm': active_alarm})
    except AdminApiException as e:
        msg = "[{}] Cannot get active alarms via Admin API".format(connection_alias)
        logging.error(msg)
        logging.debug(repr(e))
        _append_to_truck_roll_alarms_variable(msg)


def _verify_rus_are_in_truck_roll_state(bts_type, bts_id, du_id=0):
    """
    Verify if any RU is in Truck Roll state. Truck Roll state means that Ru have 'Not Installed' status.
    :param bts_type: 'GNB' or 'ENB'
    :param bts_id: BTS id
    :param du_id: DU id
    :return: None
    """
    ru = GnbRuOperations() if bts_type == 'GNB' else EnbRuOperations()
    bts_alias = ru.rest_alias.format(bts_id, du_id)
    try:
        radio_units_in_truck_roll_state = []
        for ru_info in ru.get_all_notinstalled_radio_units(bts_id=bts_id, du_id=du_id):
            try:
                ru_conf = ru_info.get('id', {}).get('configuration', '').split('/')[-1] or 'Unknown RU'
            except (IndexError, AttributeError):
                ru_conf = 'Unknown RU'
            ru_name = ru_info.get('productName', "Unknown RU Name")
            ru_serial = ru_info.get('serialNumber', 'Unknown Serial Number')
            ru_statuses = ru_info.get('status', 'Unknown status')
            radio_units_in_truck_roll_state.append(
                IncorrectStatuses(f"RU: {ru_conf}, {ru_name}, {ru_serial} have incorrect statuses: {ru_statuses}")
            )
        if radio_units_in_truck_roll_state:
            e = IncorrectRUsStatuses(radio_units_in_truck_roll_state)
            msg = f"[{bts_alias}] Some RUs are in Truck Roll state: [{e}]"
            logging.error(msg)
            logging.debug(repr(e))
            _append_to_truck_roll_alarms_variable(msg)
    except RUsInfoNotAvailable as e:
        msg = f"[{bts_alias}] Cannot get RU statuses [{e}]"
        logging.error(msg)
        logging.debug(repr(e))
        _append_to_truck_roll_alarms_variable(msg)


def _append_to_truck_roll_alarms_variable(msg):
    """
    Append message to TRUCK_ROLL_ALARMS robot variable.
    :param msg: Message to append
    :return: None
    """
    truck_roll_alarms = get_builtin_value('TRUCK_ROLL_ALARMS', [])
    truck_roll_alarms.append(msg)
    set_robot_suite_variable('TRUCK_ROLL_ALARMS', truck_roll_alarms)


def _send_email_notification(receivers, sender, cc=None, files=None):
    """
    Send email notification about truck roll alarms.
    :param receivers: List of email receivers
    :param sender: Email sender address
    :param cc: CC recipients
    :param files: Files to attach
    :return: None
    """
    cm_execution_id = os.environ.get("CM_EXECUTION_ID")
    _reason = ""
    for details in get_builtin_value('TRUCK_ROLL_ALARMS'):
        if isinstance(details, dict):
            _reason = _reason + "<li>{}<pre>{}</pre></li>".format(details['msg'], details['alarm'])
        else:
            _reason = _reason + "<li>{}</li>".format(details)
    reason = "<ul>{}</ul>".format(_reason)
    additional_info = 'Potential Truck Roll has been detected:{}<br>'.format(reason)
    if cm_execution_id:
        additional_info = additional_info + "Please set TestLine in maintenance mode ASAP <br>"
    additional_info = additional_info + """More details about Truck Roll Pronto
     under <a href='https://nokia.sharepoint.com/sites/uuf4all/SitePages/Stop&amp;Fix-for-Truck-Roll.aspx'>link</a>"""

    send_email_with_default_template(
        subject='[Action Required] Potential Truck Roll',
        additional_info=additional_info,
        receivers=receivers,
        sender=sender, cc=cc, files=files)
